public class ChatServiceGrpcImpl extends ChatServiceGrpc.ChatServiceImplBase {
    @Override
    public StreamObserver<ChatRequest> biDiChat(StreamObserver<ChatResponse> responseObserver) {
        return new StreamObserver<ChatRequest>() {
            @Override
            public void onNext(ChatRequest request) {
                // Process incoming message from client stream
                ChatResponse response = ChatResponse.newBuilder()
                    .setMessage("Echo: " + request.getMessage())
                    .build();
                responseObserver.onNext(response);
            }

            @Override
            public void onError(Throwable t) {
                // Handle dropped connection or network failure
                logger.error("Stream failed with error", t);
            }

            @Override
            public void onCompleted() {
                // Client has finished sending; close the response stream
                responseObserver.onCompleted();
            }
        };
    }
}
